404:    */
405:   async getTileOrStrip(x, y, sample, poolOrDecoder, signal) {
406:     const numTilesPerRow = Math.ceil(this.getWidth() / this.getTileWidth());
407:     const numTilesPerCol = Math.ceil(this.getHeight() / this.getTileHeight());
408:     let index;
409:     const { tiles } = this;
410:     if (this.planarConfiguration === 1) {
411:       index = (y * numTilesPerRow) + x;
412:     } else if (this.planarConfiguration === 2) {
413:       index = (sample * numTilesPerRow * numTilesPerCol) + (y * numTilesPerRow) + x;
414:     }
415:     if (index === undefined) {
416:       throw new Error('Could not determine tile or strip index.');
417:     }
418: 
419:     let offset;
420:     let byteCount;
421:     if (this.isTiled) {
422:       offset = Number(await this.fileDirectory.loadValueIndexed('TileOffsets', index));
423:       byteCount = Number(await this.fileDirectory.loadValueIndexed('TileByteCounts', index));
424:     } else {
425:       offset = Number(await this.fileDirectory.loadValueIndexed('StripOffsets', index));
426:       byteCount = Number(await this.fileDirectory.loadValueIndexed('StripByteCounts', index));
427:     }
428: 
429:     if (byteCount === 0) {
430:       const nPixels = this.getBlockHeight(y) * this.getTileWidth();
431:       const bytesPerPixel = (this.planarConfiguration === 2) ? this.getSampleByteSize(sample) : this.getBytesPerPixel();
432:       const data = new ArrayBuffer(nPixels * bytesPerPixel);
433:       const view = this.getArrayForSample(sample, data);
434:       view.fill(this.getGDALNoData() || 0);
435:       return { x, y, sample, data };
436:     }
437: 
438:     const slice = (await this.source.fetch([{ offset, length: byteCount }], signal))[0];
439: 
440:     let request;
441:     if (tiles === null || !tiles[index]) {
442:     // resolve each request by potentially applying array normalization
443:       request = (async () => {
444:         let data = await poolOrDecoder.decode(slice);
445:         const sampleFormat = /** @type {1|2|3} */ (this.getSampleFormat());
446:         const bitsPerSample = this.getBitsPerSample();
447:         if (needsNormalization(sampleFormat, bitsPerSample)) {
448:           data = normalizeArray(
449:             data,
450:             sampleFormat,
451:             this.planarConfiguration,
452:             this.getSamplesPerPixel(),
453:             bitsPerSample,
454:             this.getTileWidth(),
455:             this.getBlockHeight(y),
456:           );
457:         }
458:         return data;
459:       })();
460: 
461:       // set the cache
462:       if (tiles !== null) {
463:         tiles[index] = request;
464:       }
465:     } else {
466:       // get from the cache
467:       request = tiles[index];
468:     }
469: 
470:     // cache the tile request
471:     return { x, y, sample, data: await request };
472:   }
