474:   /**
475:    * Internal read function.
476:    * @private
477:    * @param {Array<number>} imageWindow The image window in pixel coordinates
478:    * @param {Array<number>} samples The selected samples (0-based indices)
479:    * @param {TypedArray|TypedArray[]} valueArrays The array(s) to write into
480:    * @param {boolean|undefined} interleave Whether or not to write in an interleaved manner
481:    * @param {DecoderWorker|import("./geotiff.js").BaseDecoder} poolOrDecoder the decoder or decoder pool
482:    * @param {number} [width] the width of window to be read into
483:    * @param {number} [height] the height of window to be read into
484:    * @param {string} [resampleMethod] the resampling method to be used when interpolating
485:    * @param {AbortSignal} [signal] An AbortSignal that may be signalled if the request is
486:    *                               to be aborted
487:    * @returns {Promise<ReadRasterResult>}
488:    */
489:   async _readRaster(imageWindow, samples, valueArrays, interleave, poolOrDecoder, width,
490:     height, resampleMethod, signal) {
491:     const tileWidth = this.getTileWidth();
492:     const tileHeight = this.getTileHeight();
493:     const imageWidth = this.getWidth();
494:     const imageHeight = this.getHeight();
495: 
496:     const minXTile = Math.max(Math.floor(imageWindow[0] / tileWidth), 0);
497:     const maxXTile = Math.min(
498:       Math.ceil(imageWindow[2] / tileWidth),
499:       Math.ceil(imageWidth / tileWidth),
500:     );
501:     const minYTile = Math.max(Math.floor(imageWindow[1] / tileHeight), 0);
502:     const maxYTile = Math.min(
503:       Math.ceil(imageWindow[3] / tileHeight),
504:       Math.ceil(imageHeight / tileHeight),
505:     );
506:     const windowWidth = imageWindow[2] - imageWindow[0];
507: 
508:     let bytesPerPixel = this.getBytesPerPixel();
509: 
510:     /** @type {Array<number>} */
511:     const srcSampleOffsets = [];
512:     /** @type {Array<(this: DataView, byteOffset: number, littleEndian: boolean) => number>} */
513:     const sampleReaders = [];
514:     for (let i = 0; i < samples.length; ++i) {
515:       if (this.planarConfiguration === 1) {
516:         const bitsPerSample = await this.fileDirectory.loadValue('BitsPerSample');
517:         if (typeof bitsPerSample !== 'object') {
518:           throw new Error('Expected BitsPerSample to be an array or typed array.');
519:         }
520:         srcSampleOffsets.push(sum(bitsPerSample, 0, samples[i]) / 8);
521:       } else {
522:         srcSampleOffsets.push(0);
523:       }
524:       sampleReaders.push(this.getReaderForSample(samples[i]));
525:     }
526: 
527:     const promises = [];
528:     const { littleEndian } = this;
529: 
530:     for (let yTile = minYTile; yTile < maxYTile; ++yTile) {
531:       for (let xTile = minXTile; xTile < maxXTile; ++xTile) {
532:         let getPromise;
533:         if (this.planarConfiguration === 1) {
534:           getPromise = this.getTileOrStrip(xTile, yTile, 0, poolOrDecoder, signal);
535:         }
536:         for (let sampleIndex = 0; sampleIndex < samples.length; ++sampleIndex) {
537:           const si = sampleIndex;
538:           const sample = samples[sampleIndex];
539:           if (this.planarConfiguration === 2) {
540:             bytesPerPixel = this.getSampleByteSize(sample);
541:             getPromise = this.getTileOrStrip(xTile, yTile, sample, poolOrDecoder, signal);
542:           }
543:           if (!getPromise) {
544:             throw new Error('Could not get tile or strip data.');
545:           }
546:           const promise = getPromise.then((tile) => {
547:             const buffer = tile.data;
548:             const dataView = new DataView(buffer);
549:             const blockHeight = this.getBlockHeight(tile.y);
550:             const firstLine = tile.y * tileHeight;
551:             const firstCol = tile.x * tileWidth;
552:             const lastLine = firstLine + blockHeight;
553:             const lastCol = (tile.x + 1) * tileWidth;
554:             const reader = sampleReaders[si];
555: 
556:             const ymax = Math.min(blockHeight, blockHeight - (lastLine - imageWindow[3]), imageHeight - firstLine);
557:             const xmax = Math.min(tileWidth, tileWidth - (lastCol - imageWindow[2]), imageWidth - firstCol);
558: 
559:             for (let y = Math.max(0, imageWindow[1] - firstLine); y < ymax; ++y) {
560:               for (let x = Math.max(0, imageWindow[0] - firstCol); x < xmax; ++x) {
561:                 const pixelOffset = ((y * tileWidth) + x) * bytesPerPixel;
562:                 const value = reader.call(
563:                   dataView, pixelOffset + srcSampleOffsets[si], littleEndian,
564:                 );
565:                 let windowCoordinate;
566:                 if (interleave) {
567:                   windowCoordinate = ((y + firstLine - imageWindow[1]) * windowWidth * samples.length)
568:                     + ((x + firstCol - imageWindow[0]) * samples.length)
569:                     + si;
570:                   valueArrays[windowCoordinate] = value;
571:                 } else {
572:                   windowCoordinate = (
573:                     (y + firstLine - imageWindow[1]) * windowWidth
574:                   ) + x + firstCol - imageWindow[0];
575:                   /** @type {TypedArray} */ (valueArrays[si])[windowCoordinate] = value;
576:                 }
577:               }
578:             }
579:           });
580:           promises.push(promise);
581:         }
582:       }
583:     }
584:     await Promise.all(promises);
585: 
586:     if ((width && (imageWindow[2] - imageWindow[0]) !== width)
587:         || (height && (imageWindow[3] - imageWindow[1]) !== height)) {
588:       let resampled;
589:       if (interleave) {
590:         resampled = resampleInterleaved(
591:           /** @type {TypedArray} */ (valueArrays),
592:           imageWindow[2] - imageWindow[0],
593:           imageWindow[3] - imageWindow[1],
594:           /** @type {number} */ (width), /** @type {number} */ (height),
595:           samples.length,
596:           resampleMethod,
597:         );
598:       } else {
599:         resampled = resample(
600:           /** @type {TypedArray[]} */ (valueArrays),
601:           imageWindow[2] - imageWindow[0],
602:           imageWindow[3] - imageWindow[1],
603:           /** @type {number} */ (width), /** @type {number} */ (height),
604:           resampleMethod,
605:         );
606:       }
607: 
608:       const resampledWithDimensions = /** @type {ReadRasterResult} */ (resampled);
609:       resampledWithDimensions.width = width ?? imageWindow[2] - imageWindow[0];
610:       resampledWithDimensions.height = height ?? imageWindow[3] - imageWindow[1];
611:       return resampledWithDimensions;
612:     }
613: 
614:     const valueArraysWithDimensions = /** @type {ReadRasterResult} */ (valueArrays);
615: 
616:     valueArraysWithDimensions.width = width || imageWindow[2] - imageWindow[0];
617:     valueArraysWithDimensions.height = height || imageWindow[3] - imageWindow[1];
618: 
619:     return valueArraysWithDimensions;
620:   }
