622:   /**
623:    * @overload
624:    * @param {ReadRastersOptions & {interleave: true}} options optional parameters
625:    * @returns {Promise<import("./geotiff.js").TypedArrayWithDimensions>} the decoded arrays as a promise
626:    */
627: 
628:   /**
629:    * @overload
630:    * @param {ReadRastersOptions & {interleave: false}} options optional parameters
631:    * @returns {Promise<import("./geotiff.js").TypedArrayArrayWithDimensions>} the decoded arrays as a promise
632:    */
633: 
634:   /**
635:    * @overload
636:    * @param {ReadRastersOptions & {interleave: boolean}} options optional parameters
637:    * @returns {Promise<ReadRasterResult>} the decoded arrays as a promise
638:    */
639: 
640:   /**
641:    * @overload
642:    * @param {ReadRastersOptions} [options={}] optional parameters
643:    * @returns {Promise<import("./geotiff.js").TypedArrayArrayWithDimensions>} the decoded arrays as a promise
644:    */
645: 
646:   /**
647:    * Reads raster data from the image. This function reads all selected samples
648:    * into separate arrays of the correct type for that sample or into a single
649:    * combined array when `interleave` is set. When provided, only a subset
650:    * of the raster is read for each sample.
651:    *
652:    * @param {ReadRastersOptions} [options={}] optional parameters
653:    * @returns {Promise<ReadRasterResult>} the decoded arrays as a promise
654:    */
655:   async readRasters(options = {}) {
656:     const {
657:       window: wnd, samples = [], pool = null,
658:       width, height, resampleMethod, fillValue, signal,
659:     } = options;
660:     const interleave = 'interleave' in options && options.interleave;
661:     const imageWindow = wnd || [0, 0, this.getWidth(), this.getHeight()];
662: 
663:     // check parameters
664:     if (imageWindow[0] > imageWindow[2] || imageWindow[1] > imageWindow[3]) {
665:       throw new Error('Invalid subsets');
666:     }
667: 
668:     const imageWindowWidth = imageWindow[2] - imageWindow[0];
669:     const imageWindowHeight = imageWindow[3] - imageWindow[1];
670:     const numPixels = imageWindowWidth * imageWindowHeight;
671:     const samplesPerPixel = this.getSamplesPerPixel();
672: 
673:     if (!samples || !samples.length) {
674:       for (let i = 0; i < samplesPerPixel; ++i) {
675:         samples.push(i);
676:       }
677:     } else {
678:       for (let i = 0; i < samples.length; ++i) {
679:         if (samples[i] >= samplesPerPixel) {
680:           return Promise.reject(new RangeError(`Invalid sample index '${samples[i]}'.`));
681:         }
682:       }
683:     }
684:     /** @type {TypedArray|TypedArray[]} */
685:     let valueArrays;
686:     if (interleave) {
687:       const { fileDirectory } = this;
688:       const sampleFormat = fileDirectory.getValue('SampleFormat');
689:       const format = sampleFormat
690:         ? Math.max.apply(null, Array.from(sampleFormat)) : 1;
691:       if (format !== 1 && format !== 2 && format !== 3) {
692:         throw new Error('Unsupported sample format for interleaved data. Must be 1, 2, or 3.');
693:       }
694:       const bitsPerSample_ = fileDirectory.getValue('BitsPerSample');
695:       const bitsPerSample = bitsPerSample_
696:         ? Math.max.apply(null, Array.from(bitsPerSample_)) : 8;
697:       valueArrays = arrayForType(format, bitsPerSample, numPixels * samples.length);
698:       if (fillValue) {
699:         if (Array.isArray(fillValue)) {
700:           throw new Error('When reading interleaved data, fillValue must be a single number.');
701:         }
702:         valueArrays.fill(fillValue);
703:       }
704:     } else {
705:       valueArrays = [];
706:       for (let i = 0; i < samples.length; ++i) {
707:         const valueArray = this.getArrayForSample(samples[i], numPixels);
708:         if (Array.isArray(fillValue) && i < fillValue.length) {
709:           valueArray.fill(fillValue[i]);
710:         } else if (fillValue && !Array.isArray(fillValue)) {
711:           valueArray.fill(fillValue);
712:         }
713:         valueArrays.push(valueArray);
714:       }
715:     }
716: 
717:     const compression = this.fileDirectory.getValue('Compression') || 1;
718:     const decoderParameters = await getDecoderParameters(compression, this.fileDirectory);
719:     const poolOrDecoder = pool
720:       ? pool.bindParameters(compression, decoderParameters)
721:       : await getDecoder(compression, decoderParameters);
722: 
723:     const result = await this._readRaster(
724:       imageWindow, samples, valueArrays, interleave, poolOrDecoder, width, height, resampleMethod, signal,
725:     );
726:     return result;
727:   }
