729:   /**
730:    * @overload
731:    * @param {ReadRGBOptions & {interleave: true}} options optional parameters
732:    * @returns {Promise<import("./geotiff.js").TypedArrayWithDimensions>} the RGB array as a Promise
733:    */
734: 
735:   /**
736:    * @overload
737:    * @param {ReadRGBOptions & {interleave: false}} options optional parameters
738:    * @returns {Promise<import("./geotiff.js").TypedArrayArrayWithDimensions>} the RGB array as a Promise
739:    */
740: 
741:   /**
742:    * @overload
743:    * @param {ReadRGBOptions & {interleave: boolean}} options optional parameters
744:    * @returns {Promise<ReadRasterResult>} the RGB array as a Promise
745:    */
746: 
747:   /**
748:    * @overload
749:    * @param {ReadRGBOptions} [options={}] optional parameters
750:    * @returns {Promise<import("./geotiff.js").TypedArrayArrayWithDimensions>} the RGB array as a Promise
751:    */
752: 
753:   /**
754:    * Reads raster data from the image as RGB.
755:    * Colorspaces other than RGB will be transformed to RGB, color maps expanded.
756:    * When no other method is applicable, the first sample is used to produce a
757:    * grayscale image.
758:    * When provided, only a subset of the raster is read for each sample.
759:    *
760:    * @param {ReadRGBOptions} [options] optional parameters
761:    * @returns {Promise<ReadRasterResult>} the RGB array as a Promise
762:    */
763:   async readRGB(options = {}) {
764:     const { window, pool = null, width, height,
765:       resampleMethod, enableAlpha = false, signal } = options;
766:     const interleave = ('interleave' in options && options.interleave) ?? false;
767:     const imageWindow = window || [0, 0, this.getWidth(), this.getHeight()];
768: 
769:     // check parameters
770:     if (imageWindow[0] > imageWindow[2] || imageWindow[1] > imageWindow[3]) {
771:       throw new Error('Invalid subsets');
772:     }
773: 
774:     const pi = this.fileDirectory.getValue('PhotometricInterpretation');
775: 
776:     if (pi === photometricInterpretations.RGB) {
777:       let s = [0, 1, 2];
778:       const extraSamples = this.fileDirectory.getValue('ExtraSamples');
779:       if (extraSamples && extraSamples[0] !== ExtraSamplesValues.Unspecified && enableAlpha) {
780:         s = [];
781:         const bitsPerSample = this.fileDirectory.getValue('BitsPerSample') || [];
782:         for (let i = 0; i < bitsPerSample.length; i += 1) {
783:           s.push(i);
784:         }
785:       }
786:       return this.readRasters({
787:         window,
788:         interleave,
789:         samples: s,
790:         pool,
791:         width,
792:         height,
793:         resampleMethod,
794:         signal,
795:       });
796:     }
797: 
798:     let samples;
799:     switch (pi) {
800:       case photometricInterpretations.WhiteIsZero:
801:       case photometricInterpretations.BlackIsZero:
802:       case photometricInterpretations.Palette:
803:         samples = [0];
804:         break;
805:       case photometricInterpretations.CMYK:
806:         samples = [0, 1, 2, 3];
807:         break;
808:       case photometricInterpretations.YCbCr:
809:       case photometricInterpretations.CIELab:
810:         samples = [0, 1, 2];
811:         break;
812:       default:
813:         throw new Error('Invalid or unsupported photometric interpretation.');
814:     }
815: 
816:     const subOptions = {
817:       window: imageWindow,
818:       /** @type {true} */
819:       interleave: true,
820:       samples,
821:       pool,
822:       width,
823:       height,
824:       resampleMethod,
825:       signal,
826:     };
827:     const { fileDirectory } = this;
828:     const raster = await this.readRasters(subOptions);
829: 
830:     const max = 2 ** this.getBitsPerSample(0);
831:     let data;
832:     switch (pi) {
833:       case photometricInterpretations.WhiteIsZero:
834:         data = fromWhiteIsZero(raster, max);
835:         break;
836:       case photometricInterpretations.BlackIsZero:
837:         data = fromBlackIsZero(raster, max);
838:         break;
839:       case photometricInterpretations.Palette:
840:         data = fromPalette(raster, /** @type {Uint16Array} */ (await fileDirectory.loadValue('ColorMap')));
841:         break;
842:       case photometricInterpretations.CMYK:
843:         data = fromCMYK(raster);
844:         break;
845:       case photometricInterpretations.YCbCr:
846:         data = fromYCbCr(raster);
847:         break;
848:       case photometricInterpretations.CIELab:
849:         data = fromCIELab(raster);
850:         break;
851:       default:
852:         throw new Error('Unsupported photometric interpretation.');
853:     }
854: 
855:     // if non-interleaved data is requested, we must split the channels
856:     // into their respective arrays
857:     if (!interleave) {
858:       const red = new Uint8Array(data.length / 3);
859:       const green = new Uint8Array(data.length / 3);
860:       const blue = new Uint8Array(data.length / 3);
861:       for (let i = 0, j = 0; i < data.length; i += 3, ++j) {
862:         red[j] = data[i];
863:         green[j] = data[i + 1];
864:         blue[j] = data[i + 2];
865:       }
866:       data = [red, green, blue];
867:     }
868: 
869:     const dataWithDimensions = /** @type {import("./geotiff.js").ReadRasterResult} */ (data);
870: 
871:     dataWithDimensions.width = raster.width;
872:     dataWithDimensions.height = raster.height;
873:     return dataWithDimensions;
874:   }
