876:   /**
877:    * Returns an array of tiepoints.
878:    * @returns {Promise<Array<{i: number, j: number, k: number, x: number, y: number, z: number}>>} the tiepoints
879:    */
880:   async getTiePoints() {
881:     if (!this.fileDirectory.hasTag('ModelTiepoint')) {
882:       return [];
883:     }
884:     const modelTiePoint = await this.fileDirectory.loadValue('ModelTiepoint');
885:     if (typeof modelTiePoint !== 'object') {
886:       throw new Error('Expected ModelTiepoint to be an array or typed array.');
887:     }
888: 
889:     const tiePoints = [];
890:     for (let i = 0; i < modelTiePoint.length; i += 6) {
891:       tiePoints.push({
892:         i: modelTiePoint[i],
893:         j: modelTiePoint[i + 1],
894:         k: modelTiePoint[i + 2],
895:         x: modelTiePoint[i + 3],
896:         y: modelTiePoint[i + 4],
897:         z: modelTiePoint[i + 5],
898:       });
899:     }
900:     return tiePoints;
901:   }
