903:   /**
904:    * Returns the parsed GDAL metadata items.
905:    *
906:    * If sample is passed to null, dataset-level metadata will be returned.
907:    * Otherwise only metadata specific to the provided sample will be returned.
908:    *
909:    * @param {number|null} [sample=null] The sample index.
910:    * @returns {Promise<Record<string, unknown>|null>} The GDAL metadata items
911:    */
912:   async getGDALMetadata(sample = null) {
913:     /** @type {Record<string, unknown>} */
914:     const metadata = {};
915:     if (!this.fileDirectory.hasTag('GDAL_METADATA')) {
916:       return null;
917:     }
918:     const string = await this.fileDirectory.loadValue('GDAL_METADATA');
919: 
920:     /** @type {Array<{inner: unknown}>} */
921:     let items = findTagsByName(string, 'Item');
922: 
923:     if (sample === null) {
924:       items = items.filter((item) => getAttribute(item, 'sample') === undefined);
925:     } else {
926:       items = items.filter((item) => Number(getAttribute(item, 'sample')) === sample);
927:     }
928: 
929:     for (let i = 0; i < items.length; ++i) {
930:       const item = items[i];
931:       metadata[getAttribute(item, 'name')] = item.inner;
932:     }
933:     return metadata;
934:   }
