936:   /**
937:    * Returns the GDAL nodata value
938:    * @returns {number|null}
939:    */
940:   getGDALNoData() {
941:     const string = this.fileDirectory.hasTag('GDAL_NODATA') && this.fileDirectory.getValue('GDAL_NODATA');
942:     if (!string) {
943:       return null;
944:     }
945:     return Number(string.substring(0, string.length - 1));
