948:   /**
949:    * Returns the image origin as a XYZ-vector. When the image has no affine
950:    * transformation, then an exception is thrown.
951:    * @returns {Array<number>} The origin as a vector
952:    */
953:   getOrigin() {
954:     const tiePoints = this.fileDirectory.getValue('ModelTiepoint');
955:     const modelTransformation = this.fileDirectory.getValue('ModelTransformation');
956:     if (tiePoints && tiePoints.length === 6) {
957:       return [
958:         tiePoints[3],
959:         tiePoints[4],
960:         tiePoints[5],
961:       ];
962:     }
963:     if (modelTransformation) {
964:       return [
965:         modelTransformation[3],
966:         modelTransformation[7],
967:         modelTransformation[11],
968:       ];
969:     }
970:     throw new Error('The image does not have an affine transformation.');
971:   }
