973:   /**
974:    * Returns the image resolution as a XYZ-vector. When the image has no affine
975:    * transformation, then an exception is thrown.
976:    * @param {GeoTIFFImage|null} [referenceImage=null] A reference image to calculate the resolution from
977:    *                                             in cases when the current image does not have the
978:    *                                             required tags on its own.
979:    * @returns {Array<number>} The resolution as a vector
980:    */
981:   getResolution(referenceImage = null) {
982:     const modelPixelScale = this.fileDirectory.getValue('ModelPixelScale');
983:     const modelTransformation = this.fileDirectory.getValue('ModelTransformation');
984: 
985:     if (modelPixelScale) {
